'use strict';
const VERSION='1', API='https://ia.socarrat.com/api/app/juego';
const screen=document.querySelector('#screen'), connection=document.querySelector('#connection');
let session=null, state=null, lastView='', pollTimer, rollingTimer, soundContext, busy=false, joined=false, tickBusy=false, registration, updating=false;
try{session=JSON.parse(localStorage.getItem('adivina-session')||'null');if(!session?.nombre||!session?.codigo)session=null;}catch{session=null;}
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function saveSession(){try{localStorage.setItem('adivina-session',JSON.stringify(session));}catch{}}
function unlockSound(){try{soundContext ||= new (window.AudioContext||window.webkitAudioContext)();soundContext.resume().catch(()=>{});}catch{}}
function beep(frequency=650,length=.08){if(!soundContext||soundContext.state!=='running')return;const osc=soundContext.createOscillator(),gain=soundContext.createGain();osc.frequency.value=frequency;gain.gain.setValueAtTime(.07,soundContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,soundContext.currentTime+length);osc.connect(gain);gain.connect(soundContext.destination);osc.start();osc.stop(soundContext.currentTime+length);}
function notice(text){connection.textContent=text;connection.hidden=!text;}
async function request(path='',body){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(API+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:controller.signal});const data=await response.json().catch(()=>({}));if(!response.ok)throw Object.assign(new Error(data.error||'No se ha podido conectar.'),{status:response.status});return data;}finally{clearTimeout(timeout);}}
function stop(){clearTimeout(pollTimer);clearTimeout(rollingTimer);}
function login(message=''){
 joined=false;state=null;stop();lastView='';document.querySelector('#scoreboard').hidden=true;document.querySelector('#leave').hidden=true;
 screen.innerHTML=`<p class="eyebrow"><span class="dot"></span> EL JUEGO DE LA CLASE</p><div class="intro"><h1>Adivina<br>el <em>personaje.</em></h1><img class="hero-icon" src="./icons/icon-512.png" alt="Personaje misterioso"></div><p class="subtitle">Un personaje secreto.<br>Una clase de detectives. ¿Quién será?</p><div class="rule"><span>Preguntas de sí o no</span><span>Por turnos</span></div><form id="join-form"><label for="name">¿CÓMO TE LLAMAS?</label><input id="name" name="name" maxlength="40" placeholder="Tu nombre" autocomplete="nickname" required value="${esc(session?.nombre||'')}"><label for="code">CÓDIGO DE LA CLASE</label><input id="code" name="code" maxlength="30" placeholder="Pídelo al profe" autocomplete="off" autocapitalize="characters" required value="${esc(session?.codigo||'')}"><p class="error" id="form-error" role="alert">${esc(message)}</p><button class="primary" id="join-button" type="submit">Entrar al juego <span>↗</span></button><p class="note">Usa un nombre que tus compañeros reconozcan.</p></form>`;
 document.querySelector('#join-form').addEventListener('submit',async e=>{e.preventDefault();unlockSound();session={nombre:document.querySelector('#name').value.trim(),codigo:document.querySelector('#code').value.trim().toUpperCase()};if(!session.nombre||!session.codigo)return;const button=document.querySelector('#join-button');button.disabled=true;button.textContent='Entrando…';try{await join();await poll();}catch(error){login(error.status===403?'Ese código no es correcto. Pregúntale al profe.':'No podemos entrar ahora. Comprueba tu conexión e inténtalo de nuevo.');}});
}
async function join(){const catalogResponse=await fetch('./famosos.json',{cache:'no-store'});if(!catalogResponse.ok)throw new Error('No se ha cargado la lista de personajes');const catalog=await catalogResponse.json();const famosos=catalog.map(p=>({nombre:p.nombre,foto:new URL(p.foto,location.href).href}));const person=await request('/entrar',{codigo:session.codigo,nombre:session.nombre,famosos});if(!person.id)throw new Error('Respuesta incompleta');session={...session,id:person.id,nombre:person.nombre||session.nombre};saveSession();joined=true;document.querySelector('#leave').hidden=false;}
function portrait(url,name){let safe='';try{const parsed=new URL(url);if(parsed.protocol==='https:')safe=parsed.href;}catch{}return safe?`<img class="portrait" src="${esc(safe)}" alt="${esc(name)}" referrerpolicy="no-referrer"><div class="fallback" hidden aria-hidden="true">?</div>`:'<div class="fallback" aria-hidden="true">?</div>';}
function refreshScores(s){const box=document.querySelector('#scoreboard');box.hidden=false;const rows=Array.isArray(s.puntos)?s.puntos:[];box.innerHTML=`<p class="section-heading" style="margin-top:0">MARCADOR</p><div class="scores">${rows.length?rows.map(p=>`<span class="score">${esc(p.nombre)}${p.nombre===session?.nombre?' · tú':''}<b>${esc(p.puntos)}</b></span>`).join(''):'<span class="muted">La primera pista está por llegar.</span>'}</div>`;}
function startRoulette(s){const names=Array.isArray(s.jugadores)?s.jugadores:[],duration=Math.max(500,Math.min(Number(s.ruletaMs)||4000,10000)),start=performance.now();let index=0;function tick(){const el=document.querySelector('#roulette-name');if(!el)return;const progress=(performance.now()-start)/duration;el.textContent=progress>=1?(s.responde||'…'):(names[index++%Math.max(1,names.length)]||'…');beep(380+Math.min(progress,1)*250,.04);if(progress<1)rollingTimer=setTimeout(tick,75+progress*260);}tick();}
function celebrate(){beep(880,.2);if(reduced)return;for(let i=0;i<28;i++){const item=document.createElement('i');item.className='confetti';item.style.cssText=`--x:${Math.random()*100}vw;--c:${i%3?'#ffed00':'#ffffff'};--r:${Math.random()*360}deg;animation-delay:${Math.random()*.6}s`;document.body.append(item);setTimeout(()=>item.remove(),3600);}}
function render(s){
 const yo=s.yo||{},phase=s.fase||'espera';
 const view=JSON.stringify([phase,yo.respondo,yo.miTurno,s.turno,s.responde,s.orden,s.jugadores,yo.eres,s.desvelado]);
 refreshScores(s);if(view===lastView)return;const oldPhase=state?.fase,oldTurn=state?.yo?.miTurno;lastView=view;clearTimeout(rollingTimer);
 if(phase==='espera')screen.innerHTML=`<p class="eyebrow"><span class="dot"></span> YA ESTÁS DENTRO, ${esc(session.nombre)}</p><img class="wait-icon" src="./icons/icon-512.png" alt=""><h1>La intriga<br><em>empieza aquí.</em></h1><p class="body-copy">Esperando a que el profe pulse <strong>Nuevo juego</strong>.</p><p class="section-heading">EN LA SALA · ${(s.jugadores||[]).length}</p><div class="players">${(s.jugadores||[]).map(n=>`<span class="pill ${n===session.nombre?'me':''}">${esc(n)}${n===session.nombre?' · tú':''}</span>`).join('')}</div>`;
 else if(phase==='ruleta'){screen.innerHTML='<p class="eyebrow">QUE DECIDA LA SUERTE</p><h1>¿A quién<br><em>le tocará?</em></h1><div class="roulette" id="roulette-name" role="status">…</div><p class="note">El profe está sorteando el personaje.</p>';startRoulette(s);}
 else if(phase==='jugando'&&yo.respondo){const person=yo.eres||{};screen.innerHTML=`<p class="eyebrow">SHHH… SOLO TÚ PUEDES VERLO</p><h1>Tú eres…</h1><div class="card secret">${portrait(person.foto,person.nombre)}<h2 class="huge-name">${esc(person.nombre||'Preparando personaje…')}</h2><p class="body-copy">Responde solo <strong>sí</strong> o <strong>no</strong>.</p></div><p class="body-copy">Pregunta <strong>${esc(s.turno||'tu compañero')}</strong>.</p><button class="primary" data-action="acierto">¡Lo ha adivinado! <span>✦</span></button><p class="note">Pulsa solo cuando la persona que pregunta acierte.</p>`;}
 else if(phase==='jugando'){const mine=!!yo.miTurno;screen.innerHTML=`<section class="turn-panel ${mine?'':'red'}"><p class="eyebrow">${mine?'ESTE ES TU MOMENTO':'ESCUCHA LAS PISTAS'}</p><h1 class="large-title">${mine?'¡Te toca<br>preguntar!':`Pregunta<br>${esc(s.turno||'…')}`}</h1><p class="body-copy">${mine?'Hazle una pregunta de sí o no a':'Responde'} <strong>${esc(s.responde)}</strong>.</p>${mine?'<button class="primary" data-action="pase">Ya he preguntado <span>→</span></button>':'<p>Piensa tu pregunta. Tu turno llegará.</p>'}</section><p class="section-heading">ORDEN DE PREGUNTAS</p><div class="players">${(s.orden||[]).map((n,i)=>`<span class="pill ${n===session.nombre?'me':''}">${i+1}. ${esc(n)}${n===session.nombre?' · tú':''}</span>`).join('')}</div>`;if(mine&&!oldTurn){beep();try{navigator.vibrate?.(100);}catch{}}}
 else if(phase==='acierto'){const reveal=s.desvelado||{};screen.innerHTML=`<p class="eyebrow">✦ ¡MISTERIO RESUELTO!</p><h1><em>${esc(reveal.acertante||'¡Acertado!')}</em><br>lo ha adivinado.</h1><div class="card">${portrait(reveal.foto,reveal.famoso)}<h2 class="huge-name">${esc(reveal.famoso)}</h2></div><p class="body-copy">Un punto más. ¿Listos para otra ronda?</p><p class="note">El profe inicia el siguiente sorteo.</p>`;if(oldPhase!=='acierto')celebrate();}
 else screen.innerHTML='<h1>Preparando<br>la ronda…</h1><p class="body-copy">Esperando al ordenador del profesor.</p>';
 screen.querySelectorAll('img.portrait').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;if(img.nextElementSibling)img.nextElementSibling.hidden=false;},{once:true}));
 screen.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>action(button.dataset.action)));
}
async function action(type){if(busy||!joined)return;busy=true;unlockSound();screen.querySelectorAll('[data-action]').forEach(b=>b.disabled=true);try{await request('/'+type,{id:session.id});notice('');}catch(error){if(error.status!==409)notice('No se ha enviado. Comprueba la conexión y vuelve a pulsar.');}finally{busy=false;screen.querySelectorAll('[data-action]').forEach(b=>b.disabled=false);await poll();}}
async function poll(){clearTimeout(pollTimer);if(!joined||tickBusy)return;tickBusy=true;try{const next=await request('?id='+encodeURIComponent(session.id));if(!joined)return;render(next);state=next;notice('');}catch(error){if(error.status===404){try{await join();state=null;lastView='';}catch(rejoinError){if(rejoinError.status===403)login('El código ha cambiado. Pídele el nuevo al profe.');else notice('Reconectando con el profe…');}}else notice('Sin conexión con el profe. Reintentando…');}finally{tickBusy=false;if(joined)pollTimer=setTimeout(poll,1000);}}
document.querySelector('#leave').addEventListener('click',()=>{joined=false;session=null;try{localStorage.removeItem('adivina-session');}catch{}notice('');login();});
document.querySelector('#help').addEventListener('click',()=>document.querySelector('#install').showModal());
document.querySelector('#close-help').addEventListener('click',()=>document.querySelector('#install').close());
async function checkVersion(){try{const latest=await fetch('./version.json?t='+Date.now(),{cache:'no-store'}).then(r=>r.ok?r.json():null);if(latest&&latest.version!==VERSION)document.querySelector('#update').hidden=false;await registration?.update();if(registration?.waiting)document.querySelector('#update').hidden=false;}catch{}}
document.querySelector('#update-button').addEventListener('click',async()=>{updating=true;const b=document.querySelector('#update-button');b.disabled=true;b.textContent='Actualizando…';try{await registration?.update();if(registration?.waiting)registration.waiting.postMessage({type:'SKIP_WAITING'});else location.reload();setTimeout(()=>location.reload(),2000);}catch{location.reload();}});
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>{registration=r;if(r.waiting)document.querySelector('#update').hidden=false;r.addEventListener('updatefound',()=>{const worker=r.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)document.querySelector('#update').hidden=false;});});}).catch(()=>{});navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updating)location.reload();});}
document.addEventListener('visibilitychange',()=>{if(!document.hidden){checkVersion();if(joined)poll();}});
window.addEventListener('online',()=>{if(joined)poll();checkVersion();});
checkVersion();setInterval(checkVersion,30000);
login();if(session){notice('Volviendo a la partida…');join().then(poll).catch(e=>{notice('');login(e.status===403?'Pídele al profe el código de esta partida.':'No hemos podido reconectar. Pulsa Entrar al juego para reintentar.');});}
